import { useState, useTransition } from 'react'
import { filterProducts, type Product } from '../lib/filterProducts'

export function ProductSearch({ products }: { products: Product[] }) {
  const [query, setQuery] = useState('')
  const [isPending, startTransition] = useTransition()
  const results = filterProducts(products, query)

  return (
    <>
      <input
        value={query}
        onChange={(e) => startTransition(() => setQuery(e.target.value))}
      />
      <ul style={{ opacity: isPending ? 0.5 : 1 }}>
        {results.map((p) => (
          <li key={p.id}>{p.name}</li>
        ))}
      </ul>
    </>
  )
}

import { memo, useDeferredValue, useState } from 'react'
import { filterProducts, type Product } from '../lib/filterProducts'

type ListProps = { products: Product[]; query: string }

const ProductList = memo(function ProductList({ products, query }: ListProps) {
  const results = filterProducts(products, query)
  return (
    <ul>
      {results.map((p) => (
        <li key={p.id}>{p.name}</li>
      ))}
    </ul>
  )
})

export function ProductSearch({ products }: { products: Product[] }) {
  const [query, setQuery] = useState('')
  const deferredQuery = useDeferredValue(query)
  const isStale = query !== deferredQuery

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <div style={{ opacity: isStale ? 0.5 : 1 }}>
        <ProductList products={products} query={deferredQuery} />
      </div>
    </>
  )
}
